/* Master's-level expansion layer. Keeps the original concise notes intact while
   replacing the deep-note library with comprehensive, syllabus-aligned content. */
(function () {
  'use strict';

  const notes = window.SM_NOTES || [];
  const byId = Object.fromEntries(notes.map((note) => [note.id, note]));
  const add = (note) => {
    if (byId[note.id]) Object.assign(byId[note.id], note);
    else { notes.push(note); byId[note.id] = note; }
  };

  add({id:'market-orientation',sec:'s1',title:'Market orientation and strategic marketing',time:'30 min',summary:'How an outside-in philosophy becomes a repeatable organisational capability and superior-value system.',chapters:'Textbook Chapters 1-2 · Study guide 3.2.1-3.2.3',
    definition:'Market orientation is the organisation-wide generation, dissemination and coordinated use of customer, competitor and market intelligence to create superior stakeholder value and sustainable performance.',
    deepDive:[
      {title:'1. Orientation is a philosophy, a behaviour and a capability',paragraphs:['A <strong>marketing orientation</strong> begins outside the firm: it asks which customers to serve, what they value, how alternatives perform and which capabilities can deliver a superior proposition. A production orientation begins with efficiency and available output; a selling orientation begins with persuasion. Neither is always irrational, but both become dangerous when they substitute internal assumptions for market evidence.','Two complementary theories sharpen the idea. <strong>Kohli and Jaworski</strong> describe market orientation behaviourally as intelligence generation, intelligence dissemination and organisational responsiveness. <strong>Narver and Slater</strong> emphasise customer orientation, competitor orientation, interfunctional coordination, long-term focus and profitability. Day adds the capabilities that make the philosophy executable: market sensing, customer linking and channel bonding.'],insight:'“Customer-led” can become reactive if the firm only follows expressed needs. Market orientation also interprets latent needs, competitors, technology, channels and the organisation’s future capability.'},
      {title:'2. The market-driven strategy system',steps:['<strong>Understand:</strong> define the product-market, sense environmental change, analyse customers and competitors, and identify segments.','<strong>Select:</strong> evaluate segment attractiveness and organisational fit; choose targets, positioning and relationship strategy.','<strong>Deliver:</strong> align product, service, price, channels and communications around the promised value.','<strong>Implement:</strong> assign resources, ownership, capabilities, incentives and timelines.','<strong>Learn:</strong> monitor customer, competitor, process and financial evidence; adapt before strategic drift widens.'],insight:'The process is iterative, not a once-a-year sequence. Implementation creates new market evidence that should alter future understanding and choice.'},
      {title:'3. Resource-based view meets market orientation',paragraphs:['The <strong>resource-based view (RBV)</strong> argues that advantage rests on valuable, rare, difficult-to-imitate and organisationally supported resources or capabilities (the VRIO logic). Market orientation prevents the RBV from becoming inward-looking: a capability is strategically valuable only if it solves a relevant market problem or captures an opportunity.','Dynamic capabilities extend the argument. In changing markets, advantage comes from repeatedly <strong>sensing</strong> opportunities and threats, <strong>seizing</strong> them through investment and business-model choices, and <strong>transforming</strong> the asset base. A legacy strength can become rigidity when managers protect it after customers and technology have moved.'],insight:'A complete advantage claim needs both sides: external value and internal defensibility.'},
      {title:'4. Diagnostic comparison',matrixHeaders:['Orientation','Starting question','Typical strength','Strategic danger'],matrix:[['Production','What can we make efficiently?','Cost, availability and consistency','Efficiency in an offer the market no longer values'],['Selling','How can we move what we made?','Persuasion and short-term volume','Pressure, low trust and weak retention'],['Market','Whom should we serve and how can we create superior value?','Relevance, learning and coordination','Overreacting to current requests or excessive research'],['Societal market','How can value remain profitable and socially legitimate?','Long-term stakeholder value','Purpose claims unsupported by operations']],insight:'Orientation is diagnosed through decisions, measures and resource allocation—not through a mission-statement claim.'},
      {title:'5. Exam blueprint',exam:['<strong>Define</strong> market orientation and distinguish it from the marketing department.','<strong>Explain mechanisms:</strong> intelligence, coordination, sensing, linking, bonding and value delivery.','<strong>Integrate:</strong> connect external opportunity to VRIO resources and dynamic capabilities.','<strong>Evaluate:</strong> discuss latent needs, customer myopia, cost, resistance and environmental turbulence.','<strong>Apply and judge:</strong> diagnose one organisation, propose capability changes and specify leading and lagging measures.'],insight:'A master’s answer treats market orientation as an organisation design problem, not a slogan about putting customers first.'}],
    trap:'Do not equate market orientation with satisfying every stated customer request. Strategic judgement balances customers, competitors, partners, capabilities, profitability and long-term stakeholder effects.',memory:'Sense → share → select → align → learn.'});

  add({id:'environment-strategy',sec:'s3',title:'Environmental, industry and competitor analysis',time:'32 min',summary:'Converting environmental signals into opportunity, threat and defensible strategic choice.',chapters:'Textbook Chapters 3, 5-6 · Study guide 3.4.1-3.4.2',
    definition:'Strategic market analysis is the disciplined interpretation of macro-environmental, industry, competitor, customer and internal evidence to identify changes that materially affect value creation and competitive position.',
    deepDive:[
      {title:'1. Use a layered diagnosis',paragraphs:['<strong>PESTLE</strong> scans political, economic, social, technological, legal and environmental forces. It should identify mechanisms and implications, not merely list trends. <strong>Porter’s Five Forces</strong> then tests industry profit pressure: rivalry, new entrants, substitutes, buyer power and supplier power. Competitor analysis examines objectives, assumptions, current strategy, resources and likely response. Internal analysis tests resources, activities, cost drivers and capabilities.','The layers answer different questions. PESTLE asks what is changing around the arena; Five Forces asks how value is divided in the arena; competitor analysis asks how particular rivals may act; capability analysis asks what the focal firm can credibly do.'],insight:'A trend is not automatically an opportunity. It becomes an opportunity only when it creates an attractive customer problem and the organisation can capture value better than alternatives.'},
      {title:'2. From signal to strategic implication',steps:['State the <strong>signal</strong> with evidence and timeframe.','Explain the <strong>causal mechanism</strong>: how will it change needs, costs, access, regulation or bargaining power?','Identify affected <strong>segments, competitors and partners</strong>.','Estimate <strong>magnitude, uncertainty, speed and reversibility</strong>.','Test the firm’s <strong>exposure and capability gap</strong>.','Develop scenarios and a response: commit, experiment, hedge, partner, monitor or exit.'],insight:'Scenario planning is not prediction. It creates a small set of plausible futures, identifies signposts and reveals choices that remain robust across more than one future.'},
      {title:'3. Strategic drift and strategic space',paragraphs:['<strong>Strategic drift</strong> occurs when incremental strategy change falls behind cumulative environmental change. Early performance can hide the widening gap; later, flux and reactive restructuring replace coherent adaptation. Cultural assumptions, sunk costs, incentive systems and success formulas explain why good organisations miss visible signals.','<strong>Strategic space</strong> lies outside the familiar competitor-product box. Substitutes, platforms, regulatory changes or new consumption behaviours may redefine the customer’s solution. A railway competes not only with other railways but with any alternative that solves mobility, time or logistics needs.'],insight:'The unit of analysis should be the customer problem and value system, not the incumbent product category.'},
      {title:'4. Framework selection',matrixHeaders:['Framework','Best question','Evidence needed','Common misuse'],matrix:[['PESTLE','Which macro forces could alter the market?','Trend direction, pace, affected actors','A long unprioritised list'],['Five Forces','Where is industry profit pressure?','Switching costs, concentration, entry barriers','Treating firms as “forces”'],['Strategic groups','Which rivals follow similar models?','Scope, price, channels, capability choices','Assuming groups never move'],['Value chain/system','Where is value created and cost incurred?','Activities, linkages, partner economics','Ignoring the customer’s value-in-use'],['VRIO','Which capabilities support advantage?','Value, rarity, imitation barriers, organisation','Calling any strength strategic']],insight:'Use fewer frameworks deeply. Triangulation is valuable when each framework contributes a different causal layer.'},
      {title:'5. Exam blueprint',exam:['Open with the focal decision and market boundary.','Prioritise two or three material forces and explain their causal effect.','Analyse industry economics and likely competitor response.','Test opportunities against capabilities, not aspiration.','Develop alternatives, decision criteria, risks and leading indicators.','Conclude conditionally and state what evidence would change the recommendation.'],insight:'Analysis earns marks when it converts evidence into implications, options and judgement.'}],trap:'Do not finish with a SWOT list. SWOT is a synthesis surface; the analytical work must establish why each factor matters and what decision follows.',memory:'Signal → mechanism → exposure → options → signposts.'});

  add({id:'digital-market-intelligence',sec:'s1',title:'Digital marketing, social media and market intelligence',time:'30 min',summary:'Designing a learning system that turns digital behaviour into better decisions without destroying trust.',chapters:'Textbook Chapters 3-4 and 18 · Study guide 3.2.4-3.2.8',definition:'Digital market intelligence is the governed process of acquiring, integrating, interpreting and activating digital and non-digital evidence to improve strategic marketing decisions.',
    deepDive:[
      {title:'1. Digital is a value system, not a channel list',paragraphs:['Digital technologies can change communication, transactions, service, distribution, data and the business model simultaneously. E-commerce includes B2B, B2C, C2B, C2C and peer-to-peer configurations; the strategic issue is who creates value, who owns the interface and data, and how revenue and risk are distributed.','The <strong>customer journey</strong> maps episodes across awareness, evaluation, purchase, use, service and advocacy. An <strong>omnichannel</strong> design integrates information and service across touchpoints; merely operating several disconnected channels is multichannel.'],insight:'Technology creates potential. Advantage depends on adoption, complementary capabilities, ecosystem position, trust and a superior customer outcome.'},
      {title:'2. Blanchard’s social media cycle',steps:['<strong>Plan:</strong> connect audiences, behaviour objectives, resources, governance and measures to business strategy.','<strong>Listen:</strong> capture relevant conversations, search behaviour, service signals and community context.','<strong>Analyse:</strong> distinguish noise from insight; test sentiment, themes, influence and causality.','<strong>Engage:</strong> respond with relevant content, service or community action and learn from the outcome.'],insight:'Engagement without listening creates noise; listening without decision rights creates dashboards without action.'},
      {title:'3. Marketing information system and research quality',paragraphs:['A marketing information system integrates internal records, marketing intelligence, research and analytical support. Primary research is collected for the focal question; secondary evidence already exists. Qualitative research explores meaning and mechanisms; quantitative research estimates patterns and relationships. Neither is inherently superior.','Quality requires validity, reliability, representative sampling, transparent definitions and a fit between the measure and decision. Observational digital data shows behaviour, not necessarily motive. Correlation, attribution and incrementality are different claims; an experiment or credible counterfactual is needed before claiming causality.'],insight:'Big data does not repair biased data. Volume can make a weak measure look precise.'},
      {title:'4. Governance test',matrixHeaders:['Question','Why it matters','Minimum safeguard','Failure signal'],matrix:[['Purpose','Limits mission creep','Purpose specification and minimisation','Data collected “just in case”'],['Consent and fairness','Protects agency and vulnerable groups','Clear choice and bias testing','Dark patterns or proxy discrimination'],['Security','Protects customers and continuity','Access control, retention limits, response plan','Unowned datasets'],['Decision value','Prevents vanity analytics','Named decision and owner','Metrics with no action threshold'],['Learning validity','Prevents false causal claims','Baseline, comparison and assumptions','Credit assigned to last click only']],insight:'Trust is both an ethical requirement and an economic asset; intrusive optimisation can reduce lifetime value.'},
      {title:'5. Exam blueprint',exam:['Define the digital value configuration and target behaviour.','Map the journey and identify the strategic friction or unmet need.','Specify the intelligence required and judge source quality.','Explain the decision rule, experiment or activation.','Evaluate privacy, bias, platform dependence and capability constraints.','Select customer, learning and financial measures; make a conditional recommendation.'],insight:'Avoid platform inventories. Trace data → insight → decision → intervention → measured outcome.'}],trap:'Do not assume observable clicks equal customer value or causal impact.',memory:'Plan → listen → validate → decide → engage → learn.'});

  add({id:'ethics-csr',sec:'s2',title:'Ethics, CSR and stakeholder value',time:'38 min',summary:'A rigorous framework for moral judgement, Carroll’s Pyramid, stakeholder governance and credible responsible marketing.',chapters:'Textbook Chapter 17 · Study guide 3.3.1-3.3.4',definition:'Marketing ethics evaluates the rightness, fairness and responsibility of marketing decisions; corporate social responsibility (CSR) governs the organisation’s economic, legal, ethical and societal obligations and impacts.',
    deepDive:[
      {title:'1. Separate ethics, CSR, sustainability and social marketing',paragraphs:['<strong>Ethics</strong> supplies principles for judging conduct even when law is silent. <strong>CSR</strong> concerns the organisation’s managed responsibilities and impacts. <strong>Sustainability</strong> asks whether economic, social and environmental value can endure across generations. <strong>Cause-related marketing</strong> links a commercial exchange to a cause; <strong>social marketing</strong> applies marketing principles primarily to voluntary behaviour change for social benefit.','Corporate citizenship describes the firm’s role and rights within society, while the <strong>triple bottom line</strong> draws attention to people, planet and profit. These ideas overlap but are not interchangeable.'],insight:'Marketing cannot compensate for irresponsible operations through communication. The claim must follow the governed activity and evidence.'},
      {title:'2. Carroll’s Pyramid of CSR',matrixHeaders:['Responsibility','Core question','Marketing implication','Critical qualification'],matrix:[['Economic','Can the firm create value and remain viable?','Useful offers, productivity, fair exchange','Profit is foundational, not a licence to externalise harm'],['Legal','Does conduct meet binding rules?','Claims, safety, competition, data and consumer law','Law is a minimum and may lag technology'],['Ethical','Is conduct fair, honest and non-harmful beyond compliance?','Targeting, pricing, persuasion, privacy, vulnerability','Stakeholders may expect more than written rules'],['Philanthropic','How does the firm contribute voluntarily?','Giving, volunteering, community investment','Cannot offset harm in the core business']],paragraphs:['Carroll’s original logic treats the four responsibilities as simultaneous expectations, not a staircase climbed once. The pyramid is memorable but has limits: responsibilities can conflict; legal and philanthropic expectations vary by country; and the model can understate ecological boundaries and power imbalances. Use it as a diagnostic, not an automatic answer.'],insight:'The strongest judgement asks whether economic viability is achieved within legal, ethical and ecological constraints—not whether profit comes “before” ethics.'},
      {title:'3. Competing theories of corporate responsibility',paragraphs:['The <strong>shareholder primacy</strong> view emphasises managers’ duties to owners within law and ethical custom. <strong>Stakeholder theory</strong> argues that value is co-created with customers, employees, suppliers, communities, financiers and others who can affect or are affected by the firm. <strong>Corporate social performance</strong> shifts attention from stated responsibility to principles, responsive processes and observable outcomes.','The <strong>shared value</strong> argument seeks business opportunities in solving social problems. It is strategically attractive but incomplete: some duties impose real cost, some stakeholders lack market power, and some harms should be prevented even when no profitable solution exists.'],insight:'Do not resolve ethical obligations only by calculating profit. A rights violation does not become acceptable merely because aggregate benefit is positive.'},
      {title:'4. Ethical lenses and seven-step decision process',matrixHeaders:['Lens','Decision test','Strength','Blind spot'],matrix:[['Utilitarian/consequence','Which option produces the greatest net wellbeing?','Makes benefits, harms and probabilities explicit','May sacrifice minorities or rights'],['Rights/duties','Does it respect truth, privacy, consent, safety and dignity?','Protects persons from instrumental use','Rights may conflict'],['Justice/fairness','Are process, risk and reward distributed fairly?','Reveals power and discrimination','Fairness principles differ'],['Virtue','What would an honest, prudent and responsible organisation do?','Connects conduct to character and culture','Can lack a precise decision rule'],['Care','How does the decision affect relationships and vulnerability?','Makes context and dependence visible','May be difficult to scale consistently']],steps:['Define the proposed action, purpose, evidence and affected group.','Map stakeholders, power, vulnerability and short/long-term effects.','Check law, codes, contracts and organisational commitments.','Apply consequences, rights, fairness, virtue and care lenses.','Generate alternatives and safeguards—not only accept/reject.','Test publicity, reversibility and precedent: could the decision be openly defended and consistently repeated?','Decide, document ownership, monitor outcomes and provide remedy.'],insight:'Multiple lenses expose assumptions. Ethical reasoning becomes managerial when it changes design, governance and remedy.'},
      {title:'5. High-risk domains',matrixHeaders:['Domain','Potential value','Ethical risk','Governance response'],matrix:[['Green marketing','Innovation and credible differentiation','Greenwashing and hidden lifecycle harm','Specific claims, boundaries, evidence and assurance'],['Children/vulnerable customers','Relevant access and education','Exploitation of limited understanding','Age-appropriate design, limits and independent review'],['Personal data/AI','Relevance, service and learning','Opaque profiling, bias, manipulation and breaches','Minimisation, consent, bias audit and appeal'],['Personalised pricing','Efficiency and tailored offers','Unfair discrimination and exploitation of urgency','Sensitive-proxy bans, caps, transparency and monitoring'],['Cause marketing','Resources and engagement','Cause-washing or weak fit','Material commitment, donation clarity and outcome reporting'],['Influencers/endorsements','Authentic reach and social proof','Hidden sponsorship and deceptive claims','Prominent disclosure and claim substantiation']],insight:'The central questions are evidence, consent, vulnerability, distribution of value, reversibility and accountability.'},
      {title:'6. CSR, brand value and greenwashing',paragraphs:['CSR can protect legitimacy, reduce regulatory and reputation risk, strengthen employee commitment, stimulate innovation, conserve resources and improve stakeholder relationships. These are causal mechanisms, not guaranteed financial returns. Effects depend on materiality, company-cause fit, execution, stakeholder awareness and credibility.','Greenwashing includes false claims, vague language, selective disclosure, irrelevant claims and promoting one minor improvement while concealing material harm. Credible communication states the scope, baseline, method, outcome, limitations and independent assurance where appropriate.'],insight:'Stakeholder scepticism is not solved by louder purpose advertising; it is solved by operational alignment and verifiable evidence.'},
      {title:'7. Exam blueprint',exam:['Define and distinguish ethics, CSR, sustainability, cause marketing and social marketing.','Use Carroll’s Pyramid, then critique its assumptions and context.','Map stakeholders and apply at least two ethical lenses.','Connect responsibility to every marketing decision: target, product, price, data, channel and communication.','Evaluate strategic mechanisms and failure risks such as greenwashing and moral licensing.','Recommend safeguards, ownership, measures and remedy; conclude conditionally.'],insight:'A high-level answer moves theory → conflict → stakeholder effects → alternatives → governance → justified judgement.'}],trap:'Do not present Carroll’s layers as sequential or philanthropy as proof that the core business is ethical.',memory:'Economic + legal + ethical + philanthropic; then test rights, outcomes and fairness.'});

  add({id:'segmentation-targeting',sec:'s3',title:'Segmentation, evaluation and targeting',time:'36 min',summary:'Building evidence-based segments and choosing where to compete through attractiveness, fit and ethical judgement.',chapters:'Textbook Chapters 7-9 · Study guide 3.4.3-3.4.6',definition:'Segmentation partitions a defined market into internally similar groups with meaningfully different needs or responses; targeting evaluates those groups and selects the customers for whom the organisation will design value.',
    deepDive:[
      {title:'1. The STP chain',steps:['<strong>Define the market</strong> through the customer problem, needs and plausible alternatives.','Choose <strong>segmentation bases</strong>: geographic, demographic/firmographic, psychographic, behavioural, benefit or needs-based.','Identify and profile segments using variables that predict different response.','Test segments for measurability, accessibility, substantiality, differentiability, actionability and reasonable stability.','Evaluate attractiveness and the firm’s competitive position.','Select a targeting pattern and design a distinct positioning and programme.'],insight:'Segmentation is useful only when it changes resource allocation or the marketing programme.'},
      {title:'2. Consumer and organisational markets',paragraphs:['Consumer demographics are observable but frequently weak explanations of choice; benefit sought, usage situation, involvement and behaviour often connect more directly to response. Psychographics add motives and lifestyles but may be difficult to measure reliably. Combining bases can increase insight while reducing segment size and practical accessibility.','In B2B markets, <strong>macro-segmentation</strong> uses organisation-level characteristics such as industry, size, technology and location. <strong>Micro-segmentation</strong> examines the buying centre, decision criteria, purchasing approach, risk and relationship preference. Derived demand and multiple decision makers make buying process evidence essential.'],insight:'A persona is a communication device, not proof that a valid segment exists.'},
      {title:'3. Segment evaluation and portfolio logic',paragraphs:['Market attractiveness may include size, growth, unmet need, profitability, competitive intensity, accessibility, risk and macro trends. Competitive position may include relevant capabilities, brand permission, cost position, channel access, relationships and ability to differentiate. Weighting and rating improve transparency but do not remove judgement. Sensitivity analysis should test whether small changes reverse the priority.','Targeting patterns include concentrated/single-segment, selective specialisation, product specialisation, market specialisation and full-market coverage. Concentration builds expertise but increases exposure; broad coverage diversifies demand but requires scale and coordination.'],insight:'The most attractive segment in isolation may be the wrong target if the firm lacks advantage or entry destroys value through retaliation and acquisition cost.'},
      {title:'4. Targeting ethics and faulty segmentation',matrixHeaders:['Risk','Diagnostic question','Potential harm','Safeguard'],matrix:[['Stereotyping','Are assumptions replacing evidence?','Exclusion and ineffective offers','Validate heterogeneity within labels'],['Vulnerability','Does the segment have reduced ability to evaluate or refuse?','Manipulation or overconsumption','Design limits and additional consent'],['Proxy discrimination','Do variables reproduce protected traits?','Unfair access or pricing','Fairness testing and human review'],['Privacy','Would customers expect this inference/use?','Loss of autonomy and trust','Minimisation and contextual transparency'],['Commercial exclusion','Who becomes unserved and with what consequence?','Access inequality','Proportionate alternatives or universal minimum']],insight:'Targeting is a resource decision and a moral decision because it allocates attention, access and persuasive pressure.'},
      {title:'5. Exam blueprint',exam:['Define the market before proposing variables.','Justify the bases through predicted differences in need or response.','Evaluate segment validity and evidence quality.','Compare attractiveness with competitive position and perform a sensitivity check.','Select and justify a targeting pattern, including risk and ethics.','Show the positioning and mix implications; conclude with measures and learning.'],insight:'The answer should form one chain, not separate lists of segmentation bases and targeting types.'}],trap:'Demographic categories are not automatically actionable segments, and a large segment is not automatically attractive.',memory:'Define → divide → validate → evaluate → select → position.'});

  add({id:'research-insight',sec:'s3',title:'Marketing research and insight quality',time:'28 min',summary:'Choosing evidence that can credibly reduce uncertainty and support a strategic decision.',chapters:'Textbook Chapters 4 and 8 · Study guide 3.4.8 and Appendix 3',definition:'Marketing research is a systematic, decision-led process of defining an information problem, designing and executing evidence collection, analysing results and communicating implications and limitations.',
    deepDive:[
      {title:'1. Start with the management decision',steps:['State the management decision and alternatives.','Translate the decision into research questions and testable propositions.','Audit existing internal and secondary evidence.','Choose exploratory, descriptive or causal design.','Define population, sampling frame, measures and ethical safeguards.','Collect, clean and analyse evidence.','Communicate implications, uncertainty, limitations and the next decision.'],insight:'A perfectly executed survey can be strategically useless if it answers the wrong question.'},
      {title:'2. Design choices and inference',matrixHeaders:['Design','Purpose','Typical methods','What it cannot prove alone'],matrix:[['Exploratory','Clarify meanings, variables and hypotheses','Interviews, observation, focus groups, desk research','Population prevalence or causal effect'],['Descriptive','Estimate who, what, when and how much','Surveys, panels, structured observation','Why a relationship occurs'],['Causal','Estimate the effect of an intervention','Randomised experiments, quasi-experiments','Universal generalisation beyond context'],['Predictive','Forecast behaviour or outcomes','Models using historical/streaming data','That predictors cause the outcome']],insight:'Method follows inference. Qualitative depth and quantitative estimation are complementary, and mixed methods often explain both pattern and mechanism.'},
      {title:'3. Validity, reliability and bias',paragraphs:['<strong>Reliability</strong> is consistency; <strong>validity</strong> is whether the measure supports the intended interpretation. A reliable scale can measure the wrong construct. Internal validity concerns causal credibility; external validity concerns transfer to the target population or context.','Coverage error, non-response, social desirability, leading questions, common-method bias and survivorship can distort findings. Statistical significance does not establish managerial importance; effect size, uncertainty, cost and decision threshold matter.'],insight:'Research quality should be judged against the decision loss it prevents, not by sample size alone.'},
      {title:'4. Exam blueprint',exam:['Define the decision and uncertainty.','Justify the research design and sampling logic.','Operationalise constructs and discuss reliability/validity.','Identify bias, ethics and data-protection safeguards.','Explain the analysis and limits of inference.','Translate findings into a conditional recommendation and further learning.'],insight:'Always state what the evidence permits you to conclude—and what it does not.'}],trap:'Do not claim causality from correlation, sentiment or a before-after comparison without a credible counterfactual.',memory:'Decision → question → design → evidence → inference → action.'});

  add({id:'crm-intelligence',sec:'s3',title:'CRM, customer value and relationship economics',time:'34 min',summary:'Selecting, acquiring, developing and retaining customers through mutual value rather than software-led contact volume.',chapters:'Textbook Chapters 4 and 13-14 · Study guide 3.4.7-3.4.8',definition:'Customer relationship management (CRM) is the cross-functional strategy and process of selecting, acquiring, retaining and developing customers where a relationship can create superior value for both customer and organisation.',
    deepDive:[
      {title:'1. Relationship strategy before technology',paragraphs:['CRM integrates customer strategy, value proposition, processes, people, governance, data and technology. The study guide’s chain—<strong>engage, segment, personalise, track</strong>—is useful when each step is governed by a clear relationship objective. Installing software before deciding which customers merit which relationship produces automated irrelevance.','Relationship marketing is not universally optimal. Some buyers prefer efficient transactions; some relationships cost more than they return; and forced loyalty can create resentment. The firm should distinguish transactional, reactive, accountable, proactive and partnership forms according to value and interdependence.'],insight:'Retention is not the objective at any cost. The objective is durable mutual value from appropriately selected relationships.'},
      {title:'2. Customer lifetime value and portfolio decisions',paragraphs:['Customer lifetime value (CLV) estimates the present value of expected contribution margin over the relationship, less acquisition and service costs. A simple logic is: expected margin × retention-adjusted duration, discounted for time and risk. More rigorous models allow changing margin, churn probability and cost.','CLV supports acquisition ceilings, service differentiation and retention priorities, but historical value can encode unequal treatment and overlook referrals, learning or strategic influence. Customer equity aggregates the lifetime values of the customer base.'],insight:'High revenue is not high value if discounts, returns, service demands, bad debt or acquisition cost absorb the margin.'},
      {title:'3. CRM failure diagnosis',matrixHeaders:['Failure','Underlying cause','Consequence','Corrective action'],matrix:[['Technology first','No customer or value strategy','Unused data and generic automation','Define segments, journeys and decisions first'],['Organisation unchanged','Silos, incentives and ownership conflict','Broken experience','Align roles, processes and rewards'],['More data is better','No purpose or minimisation','Cost, privacy risk and weak signal','Collect decision-relevant data only'],['Retention obsession','No relationship profitability test','Subsidised unprofitable loyalty','Use mutual-value and cost-to-serve analysis'],['Personalisation without trust','Opaque inference and overreach','Creepiness and opt-out','Set relevance, consent and frequency limits']],insight:'CRM performance depends on organisational change at least as much as analytical technology.'},
      {title:'4. Relationship measures',paragraphs:['Leading measures include onboarding completion, service resolution, engagement quality, consent health and product adoption. Outcome measures include retention, churn, repeat purchase, share of wallet, referral, contribution margin, CLV and customer equity. Satisfaction and Net Promoter Score are diagnostic signals, not financial outcomes and not substitutes for observed behaviour.'],insight:'A dashboard should connect experience, behaviour and economics; optimising one measure can damage another.'},
      {title:'5. Exam blueprint',exam:['Define CRM as strategy and process, not a database.','Segment customers by needs, behaviour, value and relationship potential.','Explain the mutual-value proposition and journey.','Diagnose organisational, data and technology requirements.','Use CLV cautiously and discuss ethics, cost-to-serve and vulnerability.','Recommend interventions, controls and a balanced measurement chain.'],insight:'Show why the proposed relationship form is valuable to the customer—not only how it extracts more value for the firm.'}],trap:'Do not assume every customer should be retained or every interaction personalised.',memory:'Select → engage → serve → learn → develop → value.'});

  add({id:'positioning-advantage',sec:'s4',title:'Positioning and sustainable competitive advantage',time:'36 min',summary:'Choosing a credible place in the customer’s mind and supporting it with a defensible activity system.',chapters:'Textbook Chapters 7 and 10-11 · Study guide 3.5.1',definition:'Positioning is the deliberate design and delivery of a value proposition so a target customer understands the relevant frame of reference, distinctive benefit and credible reason to choose it over alternatives.',
    deepDive:[
      {title:'1. Positioning architecture',steps:['Specify the <strong>target customer</strong> and priority situation or need.','Define the <strong>frame of reference</strong> and necessary points of parity.','Select a meaningful <strong>point of difference</strong>: functional, symbolic or experiential.','State the <strong>reason to believe</strong> and proof.','Align the entire activity system and marketing mix.','Measure mental availability, associations, preference, behaviour and economics.'],insight:'A position exists in customer perception, but management earns it through consistent operations and evidence.'},
      {title:'2. Competitive advantage and value disciplines',paragraphs:['Advantage can arise from superior benefits/differentiation, lower delivered cost, focused expertise, relationships, network effects or complementary capabilities. Porter warns against incoherent compromise, while the RBV tests whether supporting capabilities are valuable, rare, difficult to imitate and organised. The activity-system view adds fit: a constellation of reinforcing choices is harder to copy than one feature.','Treacy and Wiersema’s value disciplines—operational excellence, product leadership and customer intimacy—help clarify the dominant promise, but firms still need acceptable parity on other dimensions. Blue Ocean strategy reframes competition through value innovation and the eliminate-reduce-raise-create grid; it does not remove future imitation or execution risk.'],insight:'Differentiation is valuable only when customers notice, care, believe and will exchange enough value to cover its cost.'},
      {title:'3. Positioning failure and repositioning',matrixHeaders:['Failure','Customer perception','Likely cause','Response'],matrix:[['Under-positioning','No clear reason to choose','Generic promise','Sharpen target, benefit and proof'],['Over-positioning','Brand seen as too narrow','Excessive specialisation cues','Broaden relevant usage while preserving meaning'],['Confused positioning','Contradictory associations','Frequent or inconsistent claims','Choose hierarchy and align touchpoints'],['Doubtful positioning','Claim lacks credibility','No permission or operational proof','Build evidence/capability or change claim']],paragraphs:['Repositioning may target a new segment, alter the frame, change benefits, update proof or redesign the offer. It must weigh future relevance against the risk of alienating current customers and diluting accumulated brand associations.'],insight:'Communication-only repositioning fails when customer experience preserves the old truth.'},
      {title:'4. Perceptual maps and measurement',paragraphs:['Perceptual maps visualise how customers perceive alternatives on selected attributes. They can reveal crowded spaces or unmet preference, but axes must come from relevant customer evidence and a visible gap is not automatically profitable or feasible. Track salience, consideration, attribute associations, preference, conversion, retention, price realisation and contribution.'],insight:'Positioning effectiveness is a causal chain from intended meaning to perceived meaning, choice and financial consequence.'},
      {title:'5. Exam blueprint',exam:['Define target and frame of reference.','State parity, difference and reason to believe.','Evaluate customer relevance and competitor vulnerability.','Show capability/VRIO and activity-system support.','Translate the position into coherent mix decisions.','Assess failure risks and specify perception, behaviour and financial measures.'],insight:'A slogan is the expression of a position, not the strategy itself.'}],trap:'Do not claim uniqueness without explaining relevance, credibility and defensibility.',memory:'Target → frame → parity → difference → proof → system.'});

  add({id:'metrics-equity',sec:'s4',title:'Marketing metrics, brand equity and accountability',time:'34 min',summary:'Linking marketing activity to customer response, brand assets, cash flow and strategic learning.',chapters:'Textbook Chapters 2 and 11 · Study guide 3.5.1, Appendix 1-2',definition:'Marketing accountability is the disciplined use of linked leading and lagging measures, baselines and causal evidence to judge whether marketing creates customer, brand and financial value.',
    deepDive:[
      {title:'1. Build a measurement chain',steps:['State the objective and customer behaviour that must change.','Measure inputs and execution quality.','Track customer response: reach, cognition, experience and behaviour.','Track market outcomes: acquisition, retention, share, price and distribution.','Translate outcomes into contribution, cash flow, CLV and risk.','Compare against baseline/counterfactual and use variance for learning.'],insight:'A metric is useful when it has an owner, interpretation, decision threshold and plausible link to value.'},
      {title:'2. Core metric logic',matrixHeaders:['Metric','Question answered','Simplified logic','Caution'],matrix:[['Market share','How much category demand do we capture?','Brand sales ÷ market sales','Can rise in a shrinking/unprofitable market'],['Penetration','How many category buyers buy us?','Brand buyers ÷ category buyers','Does not show purchase depth'],['Retention/churn','Do customers remain active?','Retained ÷ eligible; churn = lost ÷ base','Definitions and observation window matter'],['CLV','What future contribution is expected?','Discounted margin less acquisition/service cost','Sensitive to retention and margin assumptions'],['ROMI','Did incremental return exceed marketing cost?','Incremental contribution less spend ÷ spend','Requires credible incrementality'],['Price premium','Can the brand realise higher value?','Brand price relative to benchmark','Mix and channel differences can distort']],insight:'Vanity metrics measure activity or attention without demonstrating incremental behaviour or economics.'},
      {title:'3. Brand equity theories',paragraphs:['<strong>Aaker’s model</strong> organises brand equity around awareness, perceived quality, associations, loyalty and proprietary assets. <strong>Keller’s customer-based brand equity pyramid</strong> moves from salience (“who are you?”), through performance/imagery and judgements/feelings, to resonance (“what relationship do we have?”). These models explain customer memory and response; financial brand valuation asks a different question.','Brand equity can lower search cost, increase trust, support extensions, improve channel leverage and sustain price. It can also become a liability when strong associations conflict with a new strategy. Extension fit, dilution and reputational spillover therefore require explicit analysis.'],insight:'Awareness is necessary in many categories but not sufficient: customers may know a brand for the wrong reason.'},
      {title:'4. Marketing mix modelling and experiments',paragraphs:['Marketing mix modelling estimates relationships between aggregate marketing inputs and outcomes over time while controlling for seasonality, trend and other variables. It is useful for broad allocation but sensitive to data quality, model specification, correlated spending and structural change. Digital attribution distributes credit across touchpoints but often mistakes observed sequence for incremental effect.','Randomised experiments provide stronger causal evidence when feasible. Geo-tests, holdouts and quasi-experiments can improve decisions when individual randomisation is impossible. No method eliminates judgement; triangulate model results, experiments and customer evidence.'],insight:'Optimise the decision, not the elegance of the model. Report ranges and assumptions rather than false precision.'},
      {title:'5. Exam blueprint',exam:['Create an objective-to-value measurement chain.','Define each metric, denominator, timing and data source.','Separate leading, diagnostic and outcome measures.','Explain attribution or counterfactual logic.','Use Aaker or Keller to interpret brand-building effects.','Evaluate gaming, short-termism and uncertainty; recommend a balanced dashboard.'],insight:'A master’s answer explains how metrics interact and where causal confidence is weak.'}],trap:'Do not call revenue generated after a campaign “return” without isolating incrementality, contribution and costs.',memory:'Objective → response → behaviour → economics → learning.'});

  add({id:'relationships-alliances',sec:'s4',title:'Strategic relationships, alliances and customer management',time:'28 min',summary:'Deciding when cooperation creates more value than arm’s-length exchange—and how to govern dependency.',chapters:'Textbook Chapters 13-15 · Study guide 3.5.2',definition:'A strategic relationship is a deliberately governed pattern of cooperation between organisations or customers that combines complementary resources to create value neither party could efficiently create alone.',
    deepDive:[
      {title:'1. Relationship continuum and rationale',paragraphs:['Relationships range from market transactions through repeat purchasing, cooperation, coordination and strategic partnership to integration. Deeper is not automatically better. Relationship-specific investment is justified when uncertainty, complexity, interdependence, knowledge sharing or switching costs make arm’s-length contracting inefficient.','Transaction cost economics compares the costs and risks of market exchange with coordination or ownership. The relational view emphasises joint assets, knowledge sharing, complementary resources and governance as sources of inter-organisational advantage.'],insight:'The strategic question is the appropriate governance form for the value and risk—not whether partnership sounds desirable.'},
      {title:'2. Partner selection and governance',steps:['Define the customer value and capability gap.','Assess strategic fit, complementary resources and cultural/operational compatibility.','Model value creation, appropriation and each party’s alternatives.','Identify dependency, leakage, opportunism, regulatory and reputation risks.','Choose contracts, decision rights, information sharing, incentives and escalation.','Set relationship and outcome measures, learning reviews and exit provisions.'],insight:'Trust reduces coordination cost but does not replace governance; contracts cannot specify every future contingency, so both formal and relational controls matter.'},
      {title:'3. Channel and alliance tensions',matrixHeaders:['Tension','Underlying issue','Failure mode','Governance response'],matrix:[['Value creation vs appropriation','Partners create jointly but bargain separately','One party captures disproportionate value','Transparent economics and negotiated sharing'],['Cooperation vs competition','Partners may also be rivals','Knowledge leakage or hold-up','Information boundaries and staged commitment'],['Control vs flexibility','Standards protect quality but constrain adaptation','Bureaucracy or inconsistency','Clear non-negotiables plus local discretion'],['Dependence vs reach','A powerful partner provides access','Lock-in and margin pressure','Alternatives, modularity and exit rights']],insight:'Evaluate the relationship from customer value, system economics and power—not only the focal firm’s perspective.'},
      {title:'4. Exam blueprint',exam:['State why a relationship is superior to market exchange or ownership.','Identify complementary resources and joint customer value.','Analyse bargaining power, dependency and appropriation.','Design formal and relational governance.','Specify process, relationship and outcome measures.','Judge fit, risk and exit conditions.'],insight:'Good answers distinguish relationship quality from relationship performance.'}],trap:'Do not recommend an alliance without explaining who owns the customer, data, decisions and value created.',memory:'Complementarity → joint value → power → governance → learning.'});

  add({id:'product-innovation',sec:'s4',title:'Product strategy, services and innovation',time:'34 min',summary:'Managing the benefit system, portfolio and innovation process across the product life cycle.',chapters:'Textbook Chapters 11-13 · Study guide 3.5.3',definition:'Product strategy designs and manages the bundle of core benefit, actual offer and augmented services that delivers the position across its life cycle and portfolio.',
    deepDive:[
      {title:'1. Product as a benefit system',paragraphs:['The customer buys a problem solution, not a list of attributes. The <strong>core benefit</strong> answers why the offer matters; the actual product includes design, features, quality and brand; the augmented layer includes delivery, installation, service, warranty, community and data-enabled support. Services intensify intangibility, inseparability, variability and perishability, making people, process and physical evidence important.','Jobs-to-be-done thinking asks what progress a customer is trying to make in a context. It complements, rather than replaces, segmentation: different customers may hire the same product for different jobs and value different outcomes.'],insight:'Feature superiority can destroy value if it adds complexity, cost or risk without improving the customer’s desired outcome.'},
      {title:'2. Innovation process and adoption',steps:['Identify unmet outcomes, friction and strategic opportunity.','Generate and screen concepts for desirability, feasibility, viability and strategic fit.','Develop and test concept, prototype, service process and business model.','Validate demand and economics through staged experiments.','Launch with positioning, channel readiness and adoption support.','Review evidence, improve, scale, reposition or stop.'],paragraphs:['Diffusion theory distinguishes innovators, early adopters, early majority, late majority and laggards. Relative advantage, compatibility, complexity, trialability and observability influence adoption. Crossing into the mainstream often requires a complete solution and lower perceived risk, not simply more awareness.'],insight:'Stage gates should manage uncertainty, not protect projects from disconfirming evidence.'},
      {title:'3. Product life cycle and portfolio',matrixHeaders:['Stage','Strategic priority','Typical mix implication','Critical limitation'],matrix:[['Introduction','Create category understanding and trial','Focused channels, education, adoption support','Stage length and shape vary'],['Growth','Scale, differentiate and secure access','Capacity, extensions, wider channels','Fast growth can hide poor unit economics'],['Maturity','Defend, improve value and manage cost','Reposition, loyalty, efficiency','Premature harvesting weakens the franchise'],['Decline','Harvest, niche, rejuvenate or exit','Selective support and migration','Aggregate decline may hide viable segments']],paragraphs:['Portfolio tools such as the BCG growth-share matrix create a common language for resource allocation, but market growth and relative share are crude proxies. Synergies, option value, brand roles and cash economics require additional analysis.'],insight:'The life cycle describes patterns; it does not prescribe an inevitable decision.'},
      {title:'4. Exam blueprint',exam:['Define customer outcome and product/service layers.','Connect design choices to position and target insight.','Evaluate innovation uncertainty and adoption barriers.','Locate the offer in life-cycle and portfolio context.','Integrate brand, service, channel, price and operational capability.','Recommend experiments, stage criteria and outcome measures.'],insight:'Treat innovation as a commercial and organisational system, not an idea-generation event.'}],trap:'Do not use product life cycle stage as proof; diagnose it using sales, category, competitor, customer and profitability evidence.',memory:'Outcome → concept → validate → adopt → scale → renew.'});

  add({id:'pricing-strategy',sec:'s4',title:'Strategic pricing and value capture',time:'34 min',summary:'Turning customer value, costs and competitive context into defensible price architecture.',chapters:'Textbook Chapter 11 · Study guide 3.5.3',definition:'Strategic pricing designs price levels, structures, metrics and rules to capture a fair share of created value while supporting positioning, demand, channel economics and long-term relationships.',
    deepDive:[
      {title:'1. Three anchors and the value corridor',paragraphs:['Cost establishes economic viability, customer value establishes the potential ceiling, and competitive alternatives shape the reference. Cost-plus pricing is administratively simple but ignores willingness to pay and can reward inefficiency. Competition-based pricing may surrender differentiation. Value-based pricing estimates differentiated economic and psychological value for a defined segment and use situation.','The relevant number is contribution, not revenue alone. Price affects volume, mix, acquisition, retention, channel behaviour and brand meaning; therefore the best price is not automatically the highest short-term price.'],insight:'Price is both an economic lever and a signal. A discount can increase trial while weakening reference price, trust or premium positioning.'},
      {title:'2. Pricing process',steps:['Clarify objectives, segment and positioning.','Estimate relevant fixed, variable, incremental and capacity costs.','Identify alternatives and reference prices.','Quantify economic value and research willingness to pay.','Choose price metric and structure: unit, subscription, tier, bundle, usage or outcome.','Set fences, discounts, channel terms and governance.','Test response, monitor contribution and adapt.'],insight:'Price architecture often matters more than one headline price because it determines who pays, for what unit of value and under which conditions.'},
      {title:'3. Elasticity, discrimination and behavioural effects',paragraphs:['Price elasticity measures proportional demand response to proportional price change. It varies by segment, timeframe, alternatives, share of budget and switching cost. Historical elasticity can fail after repositioning or structural change. Yield management and differentiated prices can improve utilisation and access when fences are transparent and defensible.','Behavioural effects include anchoring, reference prices, decoys, partitioned prices and perceived fairness. These mechanisms should improve comprehension and choice, not exploit confusion. Personalised pricing raises additional concerns about opaque profiling, unequal bargaining power and discrimination.'],insight:'A mathematically profitable price can be strategically poor if it trains deal-seeking, triggers retaliation, increases churn or violates fairness expectations.'},
      {title:'4. Response to a competitor price cut',matrixHeaders:['Question','Why it matters','Possible response','Risk'],matrix:[['Is the cut temporary or structural?','Determines urgency and duration','Monitor, targeted match or redesign','Overreaction'],['Which segments are affected?','Average demand hides heterogeneity','Fence response to exposed customers','Leakage'],['Is our value difference credible?','Tests price premium support','Reinforce proof or improve offer','Defensive advertising without substance'],['Can competitor sustain it?','Reveals cost and strategic intent','Hold, flank, partner or change model','Price war'],['What is lifetime effect?','Includes retention and reference price','Use selective recovery, not blanket discount','Long-term margin erosion']],insight:'Never answer a price cut automatically with another price cut.'},
      {title:'5. Exam blueprint',exam:['State pricing objective, target and position.','Analyse cost, customer value and alternatives.','Select metric, structure and fences—not only a number.','Estimate volume/contribution and customer-response scenarios.','Evaluate competition, channel, fairness and brand effects.','Recommend governance, tests and trigger points.'],insight:'Show how the price captures value without contradicting how the brand creates and communicates it.'}],trap:'Do not confuse markup with margin, revenue with contribution, or willingness to pay with ethical permission to charge.',memory:'Cost floor → value ceiling → alternatives → structure → contribution → trust.'});

  add({id:'channels-distribution',sec:'s4',title:'Distribution, channels and value networks',time:'32 min',summary:'Designing access, service and channel economics while managing power and conflict.',chapters:'Textbook Chapters 11, 14-15 · Study guide 3.5.3',definition:'Channel strategy configures the organisations, touchpoints, logistics, information and governance required to make the promised value available to target customers at an acceptable system cost.',
    deepDive:[
      {title:'1. Begin with customer service outputs',paragraphs:['Channel design begins with required service outputs: spatial convenience, waiting time, lot size, assortment, information, installation, financing, service and returns. Direct channels offer control and data but require capability and capital; intermediaries can aggregate demand, specialise and reduce transaction cost.','A value network includes upstream suppliers, complementors, platforms, intermediaries and downstream customers. Channel members perform flows—physical possession, ownership, promotion, negotiation, financing, risk, ordering, payment and information—even if one intermediary is removed.'],insight:'Disintermediation rarely removes channel functions; it reallocates them and their costs.'},
      {title:'2. Channel design process',steps:['Specify target segments and required service outputs.','Map current customer journey, flows and pain points.','Generate direct, indirect, platform and hybrid alternatives.','Evaluate coverage, control, capability, economics, flexibility and risk.','Assign roles, margins, data rights, standards and conflict mechanisms.','Pilot, measure system performance and adapt.'],insight:'Omnichannel success requires consistent promises and shared information while allowing each touchpoint to play its best role.'},
      {title:'3. Power and conflict',matrixHeaders:['Power base','Source','Potential value','Governance risk'],matrix:[['Reward','Margins, leads or incentives','Aligns desired behaviour','Dependency and gaming'],['Coercive','Ability to punish or withdraw','Enforces minimum standards','Resentment and opportunism'],['Legitimate','Contract or accepted authority','Clarity and coordination','Rigid bureaucracy'],['Expert','Knowledge or capability','Learning and superior service','Knowledge dependence'],['Referent','Brand identification','Commitment and attraction','Unequal appropriation']],paragraphs:['Conflict can be functional when it surfaces different market knowledge, but destructive when goals, roles, territory, pricing or attribution remain ambiguous. Governance combines selection, contracts, joint planning, information, incentives, trust, escalation and exit.'],insight:'Assess total-system value and its distribution; one member’s efficiency can shift hidden cost to another or to the customer.'},
      {title:'4. Exam blueprint',exam:['Define target service outputs and customer journey.','Map actors, functions, flows and economics.','Compare channel alternatives using coverage, control, cost and adaptability.','Analyse power, conflict, data ownership and partner incentives.','Connect the design to positioning and fulfilment capability.','Recommend governance and customer/system measures.'],insight:'A channel is part of the value proposition, not merely the place where a finished product is sold.'}],trap:'Do not select direct distribution solely to “remove middlemen”; prove the firm can perform the displaced functions better.',memory:'Service need → flows → structure → economics → governance → experience.'});

  add({id:'imc-strategy',sec:'s4',title:'Integrated marketing communications',time:'32 min',summary:'Designing evidence-led communication that builds memory, meaning and behaviour across paid, owned and earned contact.',chapters:'Textbook Chapter 11 · Study guide 3.5.3',definition:'Integrated marketing communications (IMC) coordinates messages, media and customer touchpoints so they reinforce a coherent positioning and produce measurable audience and behavioural effects.',
    deepDive:[
      {title:'1. Communication hierarchy and objective',paragraphs:['Models such as <strong>AIDA</strong> (attention, interest, desire, action), hierarchy of effects and DAGMAR organise possible response stages. They are planning heuristics, not universal linear laws: customers may act before forming strong attitudes, move back and forth, or rely on habit and social proof.','Set objectives for a defined audience, response and timeframe. Communication may build salience, category need, knowledge, associations, confidence, trial, repeat behaviour or advocacy. Sales alone is often too distant and influenced by price, availability and competitors.'],insight:'The objective determines the message, evidence, medium, frequency and measure. “Increase awareness” is incomplete without target, baseline, meaning and desired consequence.'},
      {title:'2. Message and media design',steps:['Identify audience insight, decision stage and barrier.','State the desired response and positioning meaning.','Develop proposition, support, tone and source.','Choose paid, owned, earned, shared and interpersonal roles.','Plan reach, frequency, sequence and creative continuity.','Pre-test comprehension and unintended meaning.','Execute, measure incremental effects and learn.'],insight:'Integration means strategic coherence, not identical creative execution in every medium.'},
      {title:'3. Promotion mix',matrixHeaders:['Tool','Strategic strength','Typical limitation','Best diagnostic'],matrix:[['Advertising','Reach, consistency and memory building','Waste and weak immediate feedback','Incremental reach and brand lift'],['Sales promotion','Trial and short-term response','Deal dependency and reference-price erosion','Incremental volume and post-promotion repeat'],['Personal selling','Adaptation and complex persuasion','High cost and variable execution','Pipeline quality, conversion and margin'],['Public relations','Credibility and stakeholder reach','Low message control','Quality of coverage and stakeholder response'],['Direct/digital','Targetability, interaction and testing','Privacy, clutter and attribution bias','Incremental action, consent and lifetime effect']],insight:'Budget by objective and marginal response, not simply last year’s percentage or competitor spending.'},
      {title:'4. Ethics, influencers and crisis communication',paragraphs:['Claims require substantiation; sponsorship and endorsements require prominent disclosure; urgency, scarcity and interface design should not impair autonomous choice. Crisis communication begins with stakeholder safety, verified facts, accountability, remedy and consistent action—not brand defence. Social media speed increases the cost of fragmented approval and unsupported claims.'],insight:'Credibility is cumulative: one deceptive execution can contaminate future messages and broader CSR claims.'},
      {title:'5. Exam blueprint',exam:['Define audience, barrier, objective and positioning.','Apply a response model but acknowledge non-linearity.','Justify proposition, evidence and source.','Assign complementary roles across the promotion mix.','Address budget, integration, ethics and execution.','Measure cognition, behaviour and incremental economics.'],insight:'Trace what communication must change in the customer’s mind or behaviour and how that change creates value.'}],trap:'Do not treat clicks, impressions or media equivalence as proof of business impact.',memory:'Audience → barrier → response → message → media → incrementality.'});

  add({id:'marketing-mix-plan',sec:'s4',title:'Integrated marketing strategy and the marketing plan',time:'38 min',summary:'Turning diagnosis and positioning into a coherent programme, resource commitment and learning contract.',chapters:'Textbook Chapters 2 and 11 · Study guide 3.5.3-3.5.4 and Appendix 3',definition:'A strategic marketing plan is an evidence-based commitment that connects situation diagnosis, objectives, target and positioning choices, coordinated programmes, resources, responsibilities, risks and controls.',
    deepDive:[
      {title:'1. The planning hierarchy',paragraphs:['Corporate strategy determines purpose, scope and resource logic; business strategy determines how a unit will compete; marketing strategy specifies target markets, value propositions and routes to market; the marketing plan operationalises programmes, budgets and controls. Strategic marketing is proactive and long-term, whereas day-to-day marketing management coordinates current execution.','The plan is both forecast and control system. It should make assumptions visible so that managers can distinguish poor execution from a changed environment or a flawed strategy.'],insight:'A plan is valuable because it forces integrated choices and creates a basis for learning—not because its forecast will be exactly correct.'},
      {title:'2. SOSTAC and coherent planning',steps:['<strong>Situation:</strong> where are we now—customers, market, competitors, capabilities, performance and assumptions?','<strong>Objectives:</strong> where do we want to go—specific customer, market and financial outcomes?','<strong>Strategy:</strong> how will we win—segments, target, positioning, relationships and strategic logic?','<strong>Tactics:</strong> which integrated product, service, price, channel and communication choices deliver it?','<strong>Action:</strong> who does what, when, with which resources and dependencies?','<strong>Control:</strong> which measures, thresholds, reviews and contingencies govern adaptation?'],insight:'SMART makes objectives administratively clear; it does not prove they are strategically relevant or mutually consistent.'},
      {title:'3. Marketing mix coherence',matrixHeaders:['Decision','Value-creation question','Key dependency','Misalignment example'],matrix:[['Product/service','What customer outcome is designed?','Operations, innovation and service','Premium claim with unreliable delivery'],['Price','How is value signalled and captured?','Cost, willingness to pay and channel','Discounting that erodes exclusivity'],['Place/channel','How is value made accessible?','Partners, logistics and data','Convenience position with poor availability'],['Promotion','How is meaning and action created?','Proof, media and experience','Sustainability claims without evidence'],['People/process/evidence','How is service promise enacted?','Culture, workflow and physical/digital cues','Relationship promise with rigid scripts']],insight:'A weakness in one element can invalidate investment in every other element.'},
      {title:'4. Forecasting, budget and risk',paragraphs:['Build forecasts from explicit volume, price, conversion, retention, capacity and cost assumptions. Use base, upside and downside scenarios and identify leading indicators. Budget methods—affordable, percentage of sales, competitive parity and objective-and-task—embed different logic; objective-and-task is strategically strongest but still requires response estimates and prioritisation.','Separate reversible experiments from irreversible commitments. A pre-mortem asks how the plan could fail; contingency triggers specify when to accelerate, adapt or stop.'],insight:'False precision hides risk. A range with clear assumptions is often more decision-useful than one elaborate point forecast.'},
      {title:'5. Exam blueprint',exam:['Diagnose and prioritise the strategic issue.','Set linked customer, market and financial objectives.','Choose STP and explain the theory of advantage.','Demonstrate mix and capability coherence.','Allocate resources using assumptions and scenarios.','Assign accountability, controls, risk triggers and learning loops.'],insight:'The conclusion should defend a coherent set of trade-offs, not recommend every possible marketing activity.'}],trap:'Do not confuse a tactical calendar with strategy or present the 4Ps as independent lists.',memory:'Situation → objectives → strategy → tactics → action → control.'});

  add({id:'implementation-audit',sec:'s5',title:'Implementation, internal marketing and strategic audit',time:'38 min',summary:'Aligning structure, systems, people and culture while using audit evidence to adapt strategy.',chapters:'Textbook Chapter 16 · Study guide 3.6.1-3.6.5',definition:'Marketing implementation converts strategic choices into coordinated behaviour and outcomes; a strategic marketing audit independently and systematically tests the strategy, environment, systems and performance to identify corrective priorities.',
    deepDive:[
      {title:'1. Why implementation fails',paragraphs:['Failure can arise from weak strategy, poor translation or changed assumptions. Common barriers include ambiguous priorities, resource mismatch, silo conflict, slow decisions, capability gaps, inconsistent incentives, political resistance and measures that reward legacy behaviour. Labelling all underperformance “execution” protects flawed strategy from scrutiny.','McKinsey’s <strong>7S</strong> framework—strategy, structure, systems, shared values, style, staff and skills—shows why isolated training or restructuring rarely fixes misalignment. The <strong>balanced scorecard</strong> connects learning/capability, internal process, customer and financial outcomes through hypothesised cause-and-effect links.'],insight:'Implementation is strategy under real organisational constraints; it should influence strategy design from the beginning.'},
      {title:'2. Internal marketing and change',paragraphs:['Internal marketing treats employees and partners as participants who must understand, believe, be equipped for and be rewarded for delivering the promise. It is more than internal communication: decision rights, tools, workload, recruitment, training, leadership behaviour and incentives must support the expected customer experience.','Kotter’s change principles and Lewin’s unfreeze-change-refreeze logic highlight urgency, coalition, vision, enablement, wins and institutionalisation. In turbulent environments “refreezing” is temporary; routines must preserve learning and adaptation rather than freeze one solution.'],insight:'Employees cannot deliver a customer promise that operating policy makes impossible.'},
      {title:'3. Implementation architecture',steps:['Translate strategy into a small number of outcomes and non-negotiable choices.','Map initiatives, dependencies, owners and decision rights using a clear accountability model such as RACI.','Allocate budget, people, technology and partner capacity.','Align processes, policies, incentives, skills and leadership signals.','Pilot where uncertainty is high; manage adoption and service continuity.','Review leading and lagging measures; escalate, learn and reallocate.'],insight:'Milestones show activity; benefits realisation shows whether the activity changed capability, customer behaviour and economics.'},
      {title:'4. Strategic marketing audit',matrixHeaders:['Audit domain','Core question','Evidence','Possible response'],matrix:[['Environment','Have material assumptions changed?','Customers, competitors, PESTLE, channels','Reframe opportunity or scenario'],['Strategy','Are objectives, STP and advantage coherent?','Choice logic and market response','Focus, reposition or exit'],['Organisation','Can structure and culture deliver?','Roles, incentives, skills, conflict','Redesign and internal marketing'],['Systems','Do information, planning and control support learning?','Data quality, decisions, review cadence','Repair measures and governance'],['Productivity','Do activities create sufficient value?','Contribution, CLV, ROMI, cost-to-serve','Reallocate, experiment or stop'],['Functions','Are mix programmes coherent and effective?','Product, price, channel, IMC evidence','Correct execution and integration']],paragraphs:['A robust audit is comprehensive, systematic, independent and periodic. It compares performance with explicit expectations and examines causes, not merely variances. Recommendations should be prioritised by value, urgency, feasibility and dependency.'],insight:'The audit is a forward-looking learning mechanism, not a compliance ritual or retrospective blame exercise.'},
      {title:'5. Exam blueprint',exam:['Separate strategy-quality, execution and environmental-change hypotheses.','Use 7S to diagnose organisational alignment.','Explain internal marketing as capability and behaviour change.','Design ownership, resources, milestones and feedback.','Structure a comprehensive, independent and periodic audit.','Recommend prioritised actions and a balanced scorecard with trigger points.'],insight:'Every recommendation should name a cause, owner, mechanism, measure and review point.'}],trap:'Do not recommend communication or training when incentives, authority, process or capacity contradict the strategy.',memory:'Translate → own → resource → align → measure → adapt.'});

  add({id:'disruption-response',sec:'s5',title:'Disruption, platforms and the Uber strategic case',time:'32 min',summary:'Diagnosing changed value architecture and designing an adaptive incumbent or entrant response.',chapters:'Textbook Chapters 3, 12 and 18 · Study guide 3.6 and Uber case',definition:'Market disruption occurs when a new value configuration changes customer expectations, industry economics or access sufficiently to weaken established advantage; technology may enable disruption but is not itself the strategic explanation.',
    deepDive:[
      {title:'1. Decompose the disruptive mechanism',steps:['Identify the customer friction and changed expectation.','Separate enabling technology from the value proposition and business model.','Map complements, participants, data and payment flows.','Analyse network effects, liquidity, trust mechanisms and unit economics.','Assess regulation, worker/supplier economics, legitimacy and externalities.','Test whether incumbent resources are advantages, rigidities or both.'],insight:'Calling an entrant “digital” explains the interface, not why value migrated.'},
      {title:'2. Uber as a platform case',paragraphs:['Uber combined smartphone location, algorithmic matching, cashless payment, ratings and flexible supply to reduce search, waiting and transaction friction. The platform’s local value depends on liquidity: more suitable drivers can improve wait times and attract riders, which can attract more drivers. Network effects are constrained by multi-homing, local regulation, congestion, switching ease and the need to subsidise participation.','Strategic evaluation must include rider convenience, driver earnings and control, platform take rate, safety, accessibility, public infrastructure, data power and regulatory legitimacy. Growth or gross bookings alone do not prove sustainable value creation.'],insight:'A platform can create genuine customer value and still face unresolved questions about value distribution and social cost.'},
      {title:'3. Incumbent response options',matrixHeaders:['Response','When appropriate','Capability requirement','Risk'],matrix:[['Defend/differentiate','Legacy segment values trust, coverage or service','Clear proposition and operational proof','Denial of changing baseline'],['Build','Digital capability is strategically core','Capital, talent, data and speed','Slow imitation'],['Partner','Complementary assets exist','Governance and integration','Dependency and value leakage'],['Acquire','Time/capability gap is severe','Integration and valuation discipline','Overpayment and cultural loss'],['Reconfigure model','Old economics no longer fit','Leadership and cannibalisation tolerance','Execution shock'],['Exit/harvest','No credible path to advantage','Capital discipline and transition','Late exit destroys value']],insight:'Copying visible features is insufficient when the entrant’s economics, ecosystem and operating model differ.'},
      {title:'4. Ambidexterity and real options',paragraphs:['Organisational ambidexterity balances exploitation of the current model with exploration of new models. Separation can protect experimentation from legacy metrics, but the new unit still needs access to relevant assets and an integration logic. Real-options thinking stages investment: small experiments purchase learning while limiting downside, with explicit criteria for scaling or abandonment.'],insight:'Experimentation is not indecision when hypotheses, evidence thresholds and follow-on commitments are specified.'},
      {title:'5. Exam blueprint',exam:['Define the disrupted customer job and changed value architecture.','Explain platform mechanisms and unit economics.','Map stakeholders, regulation and legitimacy—not only users and shareholders.','Diagnose incumbent assets, rigidities and strategic drift.','Compare response options using value, feasibility, speed and risk.','Recommend staged action, signposts and governance; conclude conditionally.'],insight:'A strong case answer judges whether value creation, value capture and stakeholder legitimacy can endure together.'}],trap:'Do not assume network effects guarantee monopoly or that high adoption proves profitable unit economics.',memory:'Friction → new architecture → network → economics → legitimacy → response.'});

  window.SM_NOTES = notes;
})();
